from lib import build
R = []
FVH = "@FV"
R.append((7564027,
("Coliflor y brócoli gratinados bajos en grasa", "Esta versión baja en grasa de un clásico sigue sabiendo mucho a queso y es muy satisfactoria. El brócoli aporta color y aumenta los nutrientes.", "6", "209 g",
 ["1 cabeza de brócoli, separada en floretes (300 g)", "1 coliflor mediana, separada en floretes (500 g)", "2 cucharaditas de aceite de colza", "1 cebolla, finamente picada", "1 cucharada colmada de harina de trigo", "2 cucharaditas colmadas de mostaza Dijon", "400 ml de leche descremada", "25 g de queso Cheddar semidescremado, más 50 g rallado para cubrir", "1 cucharada de queso parmesano rallado"],
 ["Precaliente el horno a 180 °C (gas 4). Ponga la coliflor en una olla con agua hirviendo y, después de 3 minutos, agregue el brócoli. Cocine 6 minutos más, hasta que estén casi cocidos pero todavía firmes. Escurra y reserve.", "Mientras tanto, ponga el aceite en una olla y cocine la cebolla hasta que se ablande, de 3 a 4 minutos, sin que se dore. Espolvoree la harina sobre las cebollas, agregue la mostaza y revuelva suavemente durante 1 minuto para cubrir bien todas las cebollas.", "Vierta poco a poco 100 ml de la leche, mezclando para que no queden grumos. A medida que empiece a espesar, incorpore gradualmente el resto de la leche hasta formar una salsa. Agregue los 25 g de Cheddar y todo el parmesano, revolviendo hasta que los quesos se hayan derretido.", "Acomode el brócoli y la coliflor en una fuente apta para horno, vierta la salsa por encima y cubra con el Cheddar restante. Hornee de 20 a 25 minutos, hasta que la superficie se dore."],
 ["Si le sobra, licúelo con un poco de caldo de verduras o de pollo para hacer una excelente sopa.", "Este plato queda delicioso si agrega 1 cucharadita de pasta de curry a la salsa junto con la mostaza en el paso 2.", "Puede armarlo con anticipación y dejarlo en el refrigerador, y luego meterlo al horno cuando lo necesite. Si lo hornea directamente desde el refrigerador, agregue de 5 a 10 minutos más al tiempo de cocción.", "Instrucciones para congelar: se puede congelar una vez cocido. Descongele en el refrigerador o en el microondas y recaliente hasta que esté muy caliente por completo.", FVH], []),
("القرنبيط والبروكلي بالجبن قليل الدسم", "هذه النسخة قليلة الدسم من الطبق الكلاسيكي لا تزال غنية بطعم الجبن ومشبعة. ويضيف البروكلي لونًا ويعزز القيمة الغذائية.", "6", "209 غ",
 ["1 رأس بروكلي، مقسم إلى زهيرات (300 غ)", "1 رأس قرنبيط متوسط، مقسم إلى زهيرات (500 غ)", "2 ملعقة صغيرة من زيت اللفت", "1 حبة بصل، مفرومة ناعمًا", "1 ملعقة كبيرة مكدسة من الدقيق العادي", "2 ملعقة صغيرة مكدسة من خردل ديجون", "400 مل من الحليب منزوع الدسم", "25 غ من جبن الشيدر نصف الدسم + 50 غ مبشور للتغطية", "1 ملعقة كبيرة من جبن البارميزان المبشور"],
 ["سخّن الفرن مسبقًا على 180° مئوية (درجة الغاز 4). ضع القرنبيط في قدر من الماء المغلي، وبعد 3 دقائق أضف البروكلي. اطهِهما 6 دقائق إضافية حتى يوشكا على النضج ولكن يبقيا متماسكين. صفِّهما وضعهما جانبًا.", "في هذه الأثناء، ضع الزيت في قدر واطهُ البصل حتى يلين لمدة 3-4 دقائق دون أن يحمرّ. رشّ الدقيق فوق البصل، وأضف الخردل وحرّك بلطف لمدة دقيقة واحدة ليتغطى كل البصل.", "اسكب 100 مل من الحليب تدريجيًا مع الخلط للتأكد من عدم وجود كتل. وعندما يبدأ في التثخن، أضف باقي الحليب تدريجيًا مع التحريك حتى يتحول إلى صلصة. أضف 25 غ من الشيدر وكل كمية البارميزان مع التحريك حتى يذوب الجبن.", "رتّب البروكلي والقرنبيط في طبق مقاوم للحرارة، واسكب الصلصة فوقهما وغطِّهما بباقي الشيدر. اخبزه لمدة 20-25 دقيقة حتى يحمرّ وجهه."],
 ["إذا تبقى لديك منه شيء، فاخلطه مع قليل من مرق الخضار أو الدجاج للحصول على شوربة رائعة.", "يكون هذا الطبق لذيذًا عند إضافة 1 ملعقة صغيرة من معجون الكاري إلى الصلصة مع الخردل في الخطوة 2.", "يمكنك تجهيزه مسبقًا وتركه في الثلاجة ثم إدخاله إلى الفرن عند الحاجة. وإذا خبزته مباشرة من الثلاجة، فأضف 5-10 دقائق إضافية إلى وقت الطهي.", "تعليمات التجميد: يمكن تجميده بعد الطهي. اتركه يذوب في الثلاجة أو في الميكروويف، ثم أعد تسخينه حتى يصبح ساخنًا جدًا في كل جزء منه.", FVH], [])))
R.append((7568376,
("Té helado", "La bebida ideal para la merienda de las tardes calurosas de verano.", "8", "93 g",
 ["3 bolsitas de té (o té en hojas sueltas)", "750 ml de agua hirviendo", "1-4 tabletas de edulcorante (al gusto)", "1 limón, en rodajas finas", "ramitas de menta", "cubitos de hielo"],
 ["Vierta el agua hirviendo sobre las bolsitas de té y deje reposar, retirándolas cuando el té esté un poco más fuerte de lo que normalmente pensaría.", "Retire las bolsitas o cuele, luego incorpore el edulcorante. Agregue un par de rodajas de limón y deje enfriar.", "Mientras tanto, ponga en los vasos rodajas de limón y una ramita de menta, junto con unos cubitos de hielo.", "Llene una jarra hasta la mitad con cubitos de hielo, agregue el resto del limón y una ramita de menta. Luego llene la jarra con el té frío y sirva."],
 ["Pruebe con otro tipo de té, como té verde, de menta, de frutas o lapsang souchong.", "Las naranjas o las limas sirven como alternativa al limón.", FVH], []),
("الشاي المثلج", "المشروب المثالي لشاي العصر في يوم صيفي حار.", "8", "93 غ",
 ["3 أكياس شاي (أو شاي أوراق سائب)", "750 مل من الماء المغلي", "1-4 أقراص مُحلٍّ (حسب الرغبة)", "1 ليمونة، مقطعة إلى شرائح رفيعة", "أغصان نعناع", "مكعبات ثلج"],
 ["صبّ الماء المغلي فوق أكياس الشاي واتركها لتُنقع، ثم أخرجها عندما يصبح الشاي أقوى قليلًا مما تظن أنه مناسب عادةً.", "أخرج أكياس الشاي أو صفِّه، ثم أضف المُحلّي مع التحريك. أضف شريحتين من الليمون ثم ضعه جانبًا ليبرد.", "في هذه الأثناء، ضع شرائح الليمون وغصن نعناع في الأكواب، مع بعض مكعبات الثلج.", "املأ إبريقًا إلى نصفه بمكعبات الثلج، وأضف باقي الليمون وغصن نعناع. ثم املأ الإبريق بالشاي البارد وقدّمه."],
 ["جرّب استخدام أنواع مختلفة من الشاي مثل الشاي الأخضر أو شاي النعناع أو شاي الفاكهة أو اللابسانغ سوشونغ.", "يمكن استخدام البرتقال أو الليمون الأخضر بدلًا من الليمون.", FVH], [])))
R.append((7570891,
("Parmigiana de berenjena", "Este clásico italiano es una excelente opción de comida vegetariana.", "4", "650 g",
 ["2 cucharaditas de aceite de oliva", "1 cebolla grande, pelada y finamente picada", "3 dientes de ajo, pelados y finamente picados", "2 latas de 400 g de tomates picados", "4 cucharadas de puré de tomate concentrado", "1 cucharadita de orégano seco", "1 cucharadita de hierbas mixtas secas", "1 cucharadita de pimentón", "2 berenjenas medianas", "125 g de queso mozzarella reducido en grasa", "1 puñado pequeño de hojas de albahaca fresca", "25 g de queso parmesano vegetariano rallado", "25 g de harina de almendra"],
 ["Caliente 1 cucharadita de aceite en una olla grande y saltee la cebolla de 4 a 5 minutos a fuego bajo. Agregue el ajo y cocine 2 minutos, revolviendo continuamente. Añada los tomates picados, el puré de tomate y el orégano. Deje que hierva, tape y cocine a fuego lento durante 25 minutos.", "Mientras tanto, precaliente el horno a 200 °C (180 °C si es con ventilador; gas 6). Cubra un par de bandejas para hornear con papel aluminio. Corte las berenjenas a lo largo en rebanadas finas y acomódelas en una sola capa sobre las bandejas. Rocíe con el aceite de oliva restante y espolvoree con las hierbas secas y el pimentón. Hornee durante 25 minutos.", "Extienda un poco de la salsa de tomate en el fondo de una fuente para horno de 2 litros y agregue una capa de berenjenas horneadas. Esparza encima la mitad de la mozzarella y unas hojas de albahaca fresca. Repita. Cubra con el resto de la salsa.", "Mezcle el queso parmesano y la harina de almendra y esparza por encima. Hornee durante 20 minutos, hasta que burbujee. Esparza hojas de albahaca fresca y sirva con una ensalada verde mixta."],
 [FVH], []),
("باذنجان بارميجانا", "هذا الطبق الإيطالي الكلاسيكي خيار رائع لوجبة نباتية.", "4", "650 غ",
 ["2 ملعقة صغيرة من زيت الزيتون", "1 حبة بصل كبيرة، مقشرة ومفرومة ناعمًا", "3 فصوص ثوم، مقشرة ومفرومة ناعمًا", "2 علبة (400 غ لكل علبة) من الطماطم المقطعة", "4 ملاعق كبيرة من معجون الطماطم", "1 ملعقة صغيرة من الأوريجانو المجفف", "1 ملعقة صغيرة من الأعشاب المشكلة المجففة", "1 ملعقة صغيرة من البابريكا", "2 حبة باذنجان متوسطة", "125 غ من جبن الموزاريلا قليل الدسم", "حفنة صغيرة من أوراق الريحان الطازجة", "25 غ من جبن البارميزان النباتي المبشور", "25 غ من دقيق اللوز"],
 ["سخّن 1 ملعقة صغيرة من الزيت في قدر كبير وقلّب البصل لمدة 4-5 دقائق على نار هادئة. أضف الثوم واطهه لمدة دقيقتين مع التحريك المستمر. أضف الطماطم المقطعة ومعجون الطماطم والأوريجانو. اتركه يغلي، وغطِّه واتركه على نار هادئة لمدة 25 دقيقة.", "في هذه الأثناء، سخّن الفرن مسبقًا على 200° مئوية (180° مئوية لفرن المروحة؛ درجة الغاز 6). غطِّ صينيتي خَبز بورق الألومنيوم. قطّع الباذنجان بالطول إلى شرائح رفيعة ورتّبها في طبقة واحدة على الصينيتين. رشّ عليها باقي زيت الزيتون ورش فوقها الأعشاب المجففة والبابريكا. اخبزها لمدة 25 دقيقة.", "افرد قليلًا من صلصة الطماطم في قاع طبق مقاوم للحرارة سعته 2 لتر وضع فوقها طبقة من الباذنجان المخبوز. وزّع فوقها نصف كمية الموزاريلا وبضع أوراق من الريحان الطازج. كرّر الطبقات. غطِّها بباقي الصلصة.", "اخلط جبن البارميزان مع دقيق اللوز ووزّعهما فوق الطبق. اخبزه لمدة 20 دقيقة حتى يفور. وزّع أوراق الريحان الطازجة فوقه وقدّمه مع سلطة خضراء مشكلة."],
 [FVH], [])))
R.append((7571497,
("Bubble and squeak (puré de papa y repollo frito)", "Este plato caliente tradicional es una excelente manera de aprovechar las verduras sobrantes, pero use la mínima cantidad de aceite al freír para mantener bajo el contenido de grasa.", "3", "382 g",
 ["350 g de papas, en cubos", "1 chirivía grande, pelada y en cubos", "4 cucharadas de leche", "25 g de margarina a base de aceite vegetal", "1 cucharadita de aceite de colza", "1 cebolla pequeña, picada", "1 zanahoria grande, pelada y rallada", "100 g de repollo verde, finamente rallado", "3 huevos medianos", "pimienta negra recién molida"],
 ["Cocine las papas y las chirivías en agua hirviendo de 12 a 15 minutos, o hasta que estén tiernas; escurra bien y regrese a la olla. Haga un puré con la leche y la margarina hasta que quede suave, y sazone bien.", "Mientras tanto, caliente el aceite en una sartén mediana, agregue la cebolla, la zanahoria y el repollo y fría durante 5 minutos.", "Vierta sobre el puré, forme 3 tortitas y fríalas de 4 a 5 minutos, volteándolas a la mitad de la cocción.", "Escalfe los huevos y sírvalos sobre el bubble and squeak."],
 ["Para una versión sin lácteos, use aceite de colza en lugar de margarina y leche de soya en lugar de leche.", "Las coles de Bruselas quedan muy bien en lugar del repollo.", "Instrucciones para congelar: descongele en el refrigerador o en el microondas y luego recaliente hasta que esté muy caliente por completo.", "Los grupos de riesgo, como los bebés, los niños, las mujeres embarazadas, los adultos mayores y las personas enfermas, deben evitar los huevos crudos o poco cocidos, a menos que tengan la garantía de que fueron producidos bajo el programa de garantía de calidad Lion Code.", FVH], []),
("بابل آند سكويك (هريس البطاطس والملفوف المقلي)", "هذا الطبق الساخن التقليدي طريقة رائعة للاستفادة من الخضار المتبقية، لكن استخدم أقل كمية ممكنة من الزيت عند القلي للحفاظ على انخفاض محتوى الدهون.", "3", "382 غ",
 ["350 غ من البطاطس، مقطعة إلى مكعبات", "1 حبة جزر أبيض (باستيناك) كبيرة، مقشرة ومقطعة إلى مكعبات", "4 ملاعق كبيرة من الحليب", "25 غ من السمن النباتي (مارجرين) المصنوع من الزيوت النباتية", "1 ملعقة صغيرة من زيت اللفت", "1 حبة بصل صغيرة، مفرومة", "1 حبة جزر كبيرة، مقشرة ومبشورة", "100 غ من الملفوف الأخضر، مقطع شرائح رفيعة جدًا", "3 بيضات متوسطة", "فلفل أسود مطحون طازجًا"],
 ["اسلق البطاطس والجزر الأبيض في ماء مغلي لمدة 12-15 دقيقة أو حتى يلينا، ثم صفِّهما جيدًا وأعدهما إلى القدر. هرسهما مع الحليب والسمن النباتي حتى يصبحا ناعمين، وتبّلهما جيدًا.", "في هذه الأثناء، سخّن الزيت في مقلاة متوسطة، وأضف البصل والجزر والملفوف وقلّبها لمدة 5 دقائق.", "انقلها إلى الهريس، وشكّلها إلى 3 أقراص ثم اقلها لمدة 4-5 دقائق مع قلبها في منتصف الطهي.", "اسلق البيض في الماء (بيض مسلوق بدون قشر) وقدّمه فوق البابل آند سكويك."],
 ["للحصول على نسخة خالية من الألبان، استخدم زيت اللفت بدلًا من السمن النباتي والصويا بدلًا من الحليب.", "براعم بروكسل رائعة كبديل عن الملفوف.", "تعليمات التجميد: اتركه يذوب في الثلاجة أو في الميكروويف ثم أعد تسخينه حتى يصبح ساخنًا جدًا في كل جزء منه.", "ينبغي للفئات المعرّضة للخطر، مثل الرضّع والأطفال والحوامل وكبار السن والمرضى، تجنّب البيض النيئ أو غير المطهو جيدًا (ذي القلب الطري)، ما لم يكن هناك ما يضمن إنتاجه وفق نظام ضمان الجودة «Lion Code».", FVH], [])))
R.append((7571970,
("Sopa cremosa de camote y maíz", "Una sopa cremosa rápida y fácil, lista en poco más de media hora, que reúne los deliciosos sabores del camote y el maíz dulce, con un toque picante de chile, todo en una sola olla. Esta receta fue seleccionada en colaboración con Slimming World.", "4", "551 g",
 ["Aceite en aerosol bajo en calorías para cocinar", "1 cebolla, finamente picada", "1 tallo de apio, finamente picado", "2 puerros, finamente rebanados", "2 dientes de ajo, machacados", "2 ramitas de tomillo fresco, solo las hojas", "¼ de cucharadita de hojuelas de chile seco", "2 camotes medianos (unos 500 g), picados en cubos de 1 cm", "1 litro de caldo de verduras bajo en sal", "225 g de maíz dulce congelado, descongelado y calentado", "Jugo de ½ limón", "2 cucharadas de yogur griego natural sin grasa y sin azúcar, para servir", "Una pizca de pimentón ahumado, para servir", "½ paquete pequeño de cebollino fresco, picado, para servir"],
 ["Precaliente el horno a 200 °C (180 °C con ventilador; gas 6).", "Rocíe una olla grande antiadherente con un par de pulverizaciones de aceite en aerosol bajo en calorías y colóquela a fuego medio. Agregue la cebolla, el apio, los puerros, el ajo, el tomillo, las hojuelas de chile y los camotes. Fría de 6 a 8 minutos, hasta que se ablanden. Agregue el caldo, deje que hierva y cocine a fuego lento de 10 a 15 minutos, hasta que todas las verduras estén bien tiernas.", "Agregue la mitad del maíz, vuelva a llevar a fuego lento y luego licúe con una batidora de mano hasta que quede completamente suave. Agregue el jugo de limón y sazone con pimienta.", "Reparta la sopa en 4 tazones. Rocíe con el yogur, esparza el maíz restante y espolvoree con el pimentón y el cebollino. Sirva bien caliente."],
 ["Puede usar el yogur natural de su elección. Sin embargo, esto cambiará la información nutricional y la textura del plato.", "La información nutricional incluye la sugerencia de presentación.", FVH], []),
("شوربة البطاطا الحلوة والذرة الكريمية", "شوربة كريمية سريعة وسهلة، جاهزة في أكثر من نصف ساعة بقليل، وتجمع النكهات اللذيذة للبطاطا الحلوة والذرة الحلوة مع لمسة من الفلفل الحار، كلها في قدر واحد. تم اختيار هذه الوصفة بالشراكة مع Slimming World.", "4", "551 غ",
 ["بخاخ طهي قليل السعرات", "1 حبة بصل، مفرومة ناعمًا", "1 عود كرفس، مفروم ناعمًا", "2 حبة كراث، مقطعة إلى شرائح رفيعة", "2 فص ثوم، مهروس", "2 غصن زعتر طازج، مع نزع الأوراق", "¼ ملعقة صغيرة من رقائق الفلفل الحار المجفف", "2 حبة بطاطا حلوة متوسطة (حوالي 500 غ)، مقطعة إلى مكعبات بطول 1 سم", "1 لتر من مرق الخضار قليل الملح", "225 غ من الذرة الحلوة المجمدة، مذابة ومدفأة", "عصير ½ ليمونة", "2 ملعقة كبيرة من الزبادي اليوناني الطبيعي الخالي من الدسم وغير المحلى، للتقديم", "رشة من البابريكا المدخنة، للتقديم", "½ حزمة صغيرة من الثوم المعمر الطازج (الشيف)، مفرومة، للتقديم"],
 ["سخّن الفرن مسبقًا على 200° مئوية (180° مئوية لفرن المروحة؛ درجة الغاز 6).", "رشّ قدرًا كبيرًا غير لاصق ببخّتين من بخاخ الطهي قليل السعرات وضعه على نار متوسطة. أضف البصل والكرفس والكراث والثوم والزعتر ورقائق الفلفل الحار والبطاطا الحلوة. قلّبها لمدة 6-8 دقائق حتى تلين. أضف المرق، واتركه يغلي ثم دعه على نار هادئة لمدة 10-15 دقيقة حتى تلين جميع الخضار تمامًا.", "أضف نصف الذرة، وأعد الشوربة إلى الغليان الهادئ، ثم اخلطها بالخلاط اليدوي حتى تصبح ناعمة تمامًا. أضف عصير الليمون وتبّل بالفلفل.", "وزّع الشوربة على 4 أوعية. رش الزبادي فوقها، ووزّع باقي الذرة ورش البابريكا والثوم المعمر. قدّمها ساخنة جدًا."],
 ["يمكنك استخدام زبادي سادة من اختيارك. لكن ذلك سيغيّر المعلومات الغذائية وقوام الطبق.", "تشمل المعلومات الغذائية اقتراح التقديم.", FVH], [])))
R.append((7572993,
("Salteado tailandés de pollo", "Un plato bajo en calorías y lleno de sabor. Sírvalo con arroz o fideos para obtener una comida equilibrada.", "2", "324 g",
 ["1 cucharadita de aceite de girasol/colza", "2 pechugas de pollo sin hueso y sin piel, en rebanadas finas", "2 dientes de ajo, en rodajas", "2.5 cm de jengibre fresco, pelado y rallado", "1 chile rojo, en rodajas finas", "1 manojo de cebollas verdes, en rodajas", "1 pimiento rojo, sin semillas y en cubos", "ralladura y jugo de 1 lima", "1 manojo grande de albahaca", "1 cucharada de salsa de soya reducida en sal"],
 ["Caliente el aceite en una sartén o wok hasta que empiece a humear. Agregue el pollo y fría de 2 a 3 minutos, hasta que se dore; retírelo de la sartén con una espumadera y reserve.", "Agregue el ajo, el jengibre y el chile y fría 1 minuto; añada las cebollas verdes y el pimiento y siga friendo 2 minutos.", "Regrese el pollo a la sartén con el resto de los ingredientes y caliente bien, hasta que esté muy caliente. Sirva."],
 ["Esta receta también queda muy bien con cerdo magro o res en rebanadas finas, camarones, salmón, pavo o tofu en lugar de pollo.", "Es excelente envuelto en una tortilla o un roti con ensalada.", "Si no tiene a mano todas las verduras, puede usar paquetes de verduras para saltear, brotes de bambú en lata en agua o zanahorias en rodajas.", FVH], []),
("دجاج تايلندي مقلي بالتحريك", "طبق قليل السعرات ومليء بالنكهة. قدّمه مع الأرز أو النودلز للحصول على وجبة متوازنة.", "2", "324 غ",
 ["1 ملعقة صغيرة من زيت عباد الشمس/اللفت", "2 صدر دجاج منزوع العظم والجلد، مقطع إلى شرائح رفيعة", "2 فص ثوم، مقطعة إلى شرائح", "2.5 سم من الزنجبيل الطازج، مقشر ومبشور", "1 حبة فلفل أحمر حار، مقطعة إلى شرائح رفيعة", "1 حزمة بصل أخضر، مقطعة إلى شرائح", "1 حبة فلفل رومي أحمر، منزوعة البذور ومقطعة إلى مكعبات", "قشر وعصير ليمونة خضراء واحدة", "حزمة كبيرة من الريحان", "1 ملعقة كبيرة من صلصة الصويا قليلة الملح"],
 ["سخّن الزيت في مقلاة أو ووك حتى يبدأ بالتصاعد منه الدخان. أضف الدجاج وقلّبه لمدة 2-3 دقائق حتى يصبح ذهبي اللون، ثم أخرجه من المقلاة بملعقة مثقبة وضعه جانبًا.", "أضف الثوم والزنجبيل والفلفل الحار وقلّبها لمدة دقيقة واحدة، ثم أضف البصل الأخضر والفلفل الرومي وتابع التقليب لمدة دقيقتين.", "أعد الدجاج إلى المقلاة مع باقي المكونات وسخّنها جيدًا حتى تصبح ساخنة جدًا. قدّم."],
 ["تناسب هذه الوصفة أيضًا لحم الخنزير أو البقر الخالي من الدهن المقطع إلى شرائح رفيعة، أو الروبيان أو السلمون أو الديك الرومي أو التوفو بدلًا من الدجاج.", "رائع عند لفّه في تورتيلا أو خبز روتي مع السلطة.", "إذا لم تتوفر لديك كل الخضار، فيمكنك استخدام عبوات خضار جاهزة للقلي بالتحريك، أو براعم الخيزران المعلبة في الماء، أو شرائح الجزر.", FVH], [])))
R.append((7573930,
("Mini panqueques de naranja con especias", "Deliciosos mini panqueques con sabores festivos.", "25", "30 g",
 ["2 huevos, batidos", "1 cucharada de yogur sin grasa (0 %)", "1 cucharadita de extracto de almendra", "50 ml de leche descremada", "100 g de harina integral", "½ cucharadita de polvo de hornear", "3 cucharaditas de edulcorante granulado", "1 cucharadita de mezcla de especias dulces (mixed spice)", "1 cucharadita de canela", "3 naranjas: jugo y ralladura de 1 naranja, más los gajos", "ralladura de 2 naranjas, para servir", "80 g de frutas secas variadas", "1 cucharada de granos de granada"],
 ["Bata el huevo, el yogur y el extracto de almendra con la leche; luego ponga la harina, el polvo de hornear, el edulcorante y las especias en un tazón e incorpore poco a poco la mezcla de leche hasta obtener una masa suave.", "Agregue el jugo de naranja, la ralladura y las frutas secas, y mezcle bien.", "Ponga aceite en una sartén grande antiadherente. Agregue cucharadas pequeñas de postre de la mezcla a la sartén y fría de 1 a 2 minutos; luego voltee con una espátula y cocine uno o dos minutos más por el otro lado.", "Los panqueques deben medir unos 3-4 cm de diámetro y solo 3-4 mm de grosor.", "Para servir, coloque los panqueques en una fuente y cubra con los gajos de naranja; esparza la ralladura y los granos de granada."],
 ["Para sacar los gajos de la naranja con limpieza, corte la parte superior y la inferior de la naranja y colóquela sobre una tabla de cortar. Corte de arriba hacia abajo, quitando toda la cáscara y la parte blanca (la membrana amarga) sin cortar la pulpa. Una vez que haya quitado con cuidado toda la parte blanca, corte hacia un gajo, evitando la membrana, y luego gire el cuchillo para cortar hacia afuera. Así podrá sacar cada gajo sin nada de la parte blanca amarga.", "Pruebe agregar otras especias a los panqueques, como jengibre o nuez moscada, o use ralladura de limón en lugar de la de naranja.", FVH], []),
("فطائر البرتقال الصغيرة بالتوابل", "فطائر صغيرة رائعة بنكهات الأعياد.", "25", "30 غ",
 ["2 بيضة، مخفوقة", "1 ملعقة كبيرة من الزبادي (0%)", "1 ملعقة صغيرة من خلاصة اللوز", "50 مل من الحليب منزوع الدسم", "100 غ من دقيق القمح الكامل", "نصف ملعقة صغيرة من البيكنج باودر", "3 ملاعق صغيرة من المُحلّي الحبيبي", "1 ملعقة صغيرة من خلطة التوابل الحلوة (ميكسد سبايس)", "1 ملعقة صغيرة من القرفة", "3 حبات برتقال – عصير وقشر برتقالة واحدة + الفصوص", "قشر برتقالتين، للتقديم", "80 غ من الفاكهة المجففة المشكلة", "1 ملعقة كبيرة من حبوب الرمان"],
 ["اخفق البيض والزبادي وخلاصة اللوز مع الحليب، ثم ضع الدقيق والبيكنج باودر والمُحلّي والتوابل في وعاء وأضف خليط الحليب تدريجيًا مع التحريك حتى تحصل على عجينة سائلة ناعمة.", "أضف عصير البرتقال والقشر المبشور والفاكهة المجففة واخلط جيدًا.", "ضع الزيت في مقلاة كبيرة غير لاصقة. أضف ملاعق حلوى صغيرة من الخليط إلى المقلاة واقلها لمدة 1-2 دقيقة، ثم اقلبها بالملعقة المسطحة واطهها دقيقة أو دقيقتين أخريين على الجانب الآخر.", "يجب أن يبلغ قطر الفطائر حوالي 3-4 سم وسمكها 3-4 مم فقط.", "للتقديم، ضع الفطائر في طبق تقديم وزيّنها بفصوص البرتقال، ووزّع فوقها القشر المبشور وحبوب الرمان."],
 ["لفصل فصوص البرتقال بشكل أنيق، اقطع أعلى البرتقالة وأسفلها وضعها على لوح التقطيع. اقطع من الأعلى إلى الأسفل لإزالة كل القشرة مع الجزء الأبيض اللبّي دون قطع الثمرة نفسها. وبعد إزالة كل الجزء الأبيض بعناية، اقطع نحو أحد الفصوص متجنبًا الغشاء، ثم أدر السكين لتقطع نحو الخارج. وبذلك يمكنك إخراج كل فص بدون أي جزء من اللب الأبيض المر.", "جرّب إضافة توابل مختلفة إلى الفطائر مثل الزنجبيل أو جوزة الطيب، أو استخدم قشر الليمون بدلًا من قشر البرتقال.", FVH], [])))
R.append((7573996,
("Chirivías con parmesano", "Un delicioso acompañamiento de verduras para cualquier asado.", "8", "93 g",
 ["700 g de chirivías, peladas y cortadas en cuartos", "1 cucharada de margarina poliinsaturada, derretida", "2 cucharadas de queso parmesano rallado", "1 cucharadita de tomillo fresco", "pimienta negra recién molida"],
 ["Hierva las chirivías a medio cocer durante 5 minutos en una olla con agua hirviendo.", "Escurra, regréselas a la olla y mézclelas con la margarina.", "Pase a una bandeja para asar, espolvoree con el queso parmesano y el tomillo, y sazone bien.", "Ase de 25 a 30 minutos a 200 ºC (gas 6), hasta que estén doradas y tiernas."],
 ["Puede usar este método con gajos de camote o con zanahorias en lugar de chirivías.", "Para un plato vegetariano, use una alternativa al parmesano u otro queso duro de sabor fuerte.", FVH], []),
("جزر أبيض (باستيناك) بالبارميزان", "مرافق لذيذ من الخضار لأي طبق مشوي.", "8", "93 غ",
 ["700 غ من الجزر الأبيض (باستيناك)، مقشر ومقطع إلى أرباع", "1 ملعقة كبيرة من السمن النباتي غير المشبع المتعدد، مذاب", "2 ملعقة كبيرة من جبن البارميزان، مبشور", "1 ملعقة صغيرة من الزعتر الطازج", "فلفل أسود مطحون طازجًا"],
 ["اسلق الجزر الأبيض سلقًا جزئيًا لمدة 5 دقائق في قدر من الماء المغلي.", "صفِّه، ثم أعده إلى القدر وقلّبه مع السمن النباتي.", "انقله إلى صينية الشواء، ورشّ عليه جبن البارميزان والزعتر وتبّله جيدًا.", "اشوِه لمدة 25-30 دقيقة على 200° مئوية (درجة الغاز 6) حتى يصبح ذهبي اللون وطريًا."],
 ["يمكنك استخدام هذه الطريقة مع أصابع البطاطا الحلوة أو الجزر بدلًا من الجزر الأبيض.", "للحصول على طبق نباتي، استخدم بديلًا للبارميزان أو جبنًا آخر قوي النكهة وصلبًا.", FVH], [])))
R.append((7574767,
("Tagliatelle con cangrejo", "Los sabores ligeros y frescos hacen de este un sabroso plato de pasta.", "2", "408 g",
 ["150 g de tagliatelle", "200 g de tomates cherry, partidos por la mitad", "de ½ a 1 chile verde, en rodajas finas (opcional)", "6 cebollas verdes, en tiras", "125 g de carne de cangrejo blanca fresca", "1 cucharada de aceite de oliva", "2 cucharadas de albahaca fresca picada", "ralladura y jugo de 1 limón"],
 ["Cocine la pasta según las instrucciones del paquete.", "Una vez escurrida, simplemente combine todos los demás ingredientes en un tazón y mézclelos con la pasta."],
 ["Puede usar fettuccine, linguine o espagueti en lugar de tagliatelle.", "Si no tiene albahaca, use perejil.", FVH], []),
("تالياتيلي بالسلطعون", "النكهات الخفيفة والطازجة تجعل هذا الطبق معكرونة لذيذًا.", "2", "408 غ",
 ["150 غ من معكرونة التالياتيلي", "200 غ من الطماطم الكرزية، مقطعة إلى نصفين", "من نصف إلى 1 حبة فلفل أخضر حار، مقطعة إلى شرائح رفيعة (اختياري)", "6 حبات بصل أخضر، مقطعة إلى شرائح طويلة", "125 غ من لحم السلطعون الأبيض الطازج", "1 ملعقة كبيرة من زيت الزيتون", "2 ملعقة كبيرة من الريحان الطازج المفروم", "قشر مبشور وعصير ليمونة واحدة"],
 ["اطهُ المعكرونة وفق تعليمات العبوة.", "بعد تصفيتها، اخلط ببساطة جميع المكونات المتبقية في وعاء وقلّبها مع المعكرونة."],
 ["يمكنك استخدام الفيتوتشيني أو اللينغويني أو السباغيتي بدلًا من التالياتيلي.", "إذا لم يتوفر لديك الريحان، فاستخدم البقدونس بدلًا منه.", FVH], [])))
R.append((7577031,
("Puré de apio nabo", "Si quiere algo diferente para acompañar su asado, pruebe este innovador acompañamiento.", "8", "154 g",
 ["2 \"cabezas\" de apio nabo, peladas y picadas (aprox. 700 g ya peladas)", "450 g de papas, peladas y picadas", "1 diente de ajo, pelado", "4 cucharadas de crème fraîche semidescremada", "1 pizca de nuez moscada rallada", "25 g de margarina baja en grasa", "pimienta negra recién molida"],
 ["Ponga el apio nabo, las papas y el ajo en una olla con agua hirviendo ligeramente salada y cocine de 12 a 15 minutos, hasta que estén tiernos. Escurra.", "Haga un puré con los demás ingredientes y sazone bien."],
 ["Para una versión más colorida y más saludable, use camote en lugar de papas comunes.", "Instrucciones para congelar: descongele y luego caliente en el microondas para servir.", FVH], []),
("هريس الكرفس الجذري", "إذا كنت تريد شيئًا مختلفًا مع طبقك المشوي، فجرّب هذا الطبق الجانبي المبتكر.", "8", "154 غ",
 ["2 «رأس» من الكرفس الجذري، مقشرة ومقطعة (حوالي 700 غ بعد التقشير)", "450 غ من البطاطس، مقشرة ومقطعة", "1 فص ثوم، مقشر", "4 ملاعق كبيرة من الكريمة الحامضة (كريم فريش) نصف الدسم", "رشة من جوزة الطيب المبشورة", "25 غ من السمن النباتي قليل الدسم", "فلفل أسود مطحون طازجًا"],
 ["ضع الكرفس الجذري والبطاطس والثوم في قدر من الماء المغلي المملح قليلًا، واطهِها لمدة 12-15 دقيقة حتى تلين. صفِّها.", "اهرسها مع باقي المكونات وتبّلها جيدًا."],
 ["للحصول على نسخة أكثر ألوانًا وصحة، استخدم البطاطا الحلوة بدلًا من البطاطس العادية.", "تعليمات التجميد: اتركه يذوب ثم سخّنه في الميكروويف للتقديم.", FVH], [])))
R.append((7578518,
("Hamburguesas de bacalao y salmón", "Salmón y bacalao mezclados con hierbas y cebolla verde para crear una hamburguesa de pescado maravillosamente fresca, servida en un pan con ensalada crujiente.", "4", "291 g",
 ["200 g de filete de bacalao sin espinas ni piel", "200 g de salmón sin espinas ni piel", "1 huevo mediano", "jugo de ½ limón, y gajos para servir", "4 cebollas verdes, finamente picadas", "10 g de eneldo, con ramitas para servir", "pimienta molida de buena calidad", "4 panes de hamburguesa integrales, de 65 g cada uno", "12 hojas de lechuga de cogollo (little gem)", "2 tomates grandes (160 g), en rodajas", "1 cebolla morada (160 g), en rodajas finas", "6 cm de pepino, en rodajas finas"],
 ["Ponga el bacalao y la mitad del salmón en una licuadora con el huevo y el jugo de limón, y licúe hasta formar una pasta.", "Corte en cubitos pequeños el salmón restante y mézclelo con el pescado licuado, junto con las cebollas verdes, el eneldo y la pimienta. Mezcle bien; para mejores resultados, use las manos.", "Divida la mezcla en 4 porciones y forme con cada una una tortita u hamburguesa. Déjelas en el refrigerador 10 minutos mientras prepara la ensalada para servir.", "Coloque las hamburguesas de pescado en una bandeja para hornear antiadherente y cocínelas bajo el grill de 4 a 5 minutos por cada lado, hasta que estén bien cocidas por dentro.", "Sirva en un pan integral, relleno de lechuga, tomates, pepino y cebolla morada. Decore con eneldo y un gajo de limón."],
 ["Pruebe con otros pescados blancos, como carbonero.", "También puede usar otras hierbas, como perejil.", "Estas hamburguesas también son deliciosas servidas con verduras y salsa de perejil.", "Instrucciones para congelar: se pueden congelar siempre que el pescado no se haya congelado antes. Puede congelarlas antes o después de cocinarlas. Congele las hamburguesas de pescado en porciones individuales; luego descongele en el refrigerador y prepárelas como se indicó hasta que estén muy calientes por completo.", FVH], []),
("برغر القد والسلمون", "سلمون وسمك القد ممزوجان بالأعشاب والبصل الأخضر لصنع برغر سمك منعش بشكل رائع، يُقدَّم في خبز البرغر مع سلطة مقرمشة.", "4", "291 غ",
 ["200 غ من فيليه سمك القد منزوع العظم والجلد", "200 غ من السلمون منزوع العظم والجلد", "1 بيضة متوسطة", "عصير نصف ليمونة، مع أرباع ليمون للتقديم", "4 حبات بصل أخضر، مفرومة ناعمًا", "10 غ من الشبت، مع أغصان للتقديم", "فلفل مطحون عالي الجودة", "4 أرغفة برغر من القمح الكامل، 65 غ لكل رغيف", "12 ورقة خس صغير (ليتل جيم)", "2 حبة طماطم كبيرة (160 غ)، مقطعة إلى شرائح", "1 حبة بصل أحمر (160 غ)، مقطعة إلى شرائح رفيعة", "6 سم من الخيار، مقطع إلى شرائح رفيعة"],
 ["ضع سمك القد ونصف كمية السلمون في الخلاط مع البيضة وعصير الليمون، ثم اخلطها حتى تصبح عجينة.", "قطّع باقي السلمون إلى مكعبات صغيرة، ثم اخلطه مع السمك المخلوط، مع البصل الأخضر والشبت والفلفل. امزجها جيدًا، واستخدم يديك للحصول على أفضل النتائج.", "قسّم الخليط إلى 4 أجزاء وشكّل كل جزء على هيئة قرص أو برغر. اتركها في الثلاجة لمدة 10 دقائق بينما تحضّر السلطة للتقديم.", "ضع قطع برغر السمك على صينية خَبز غير لاصقة وضعها تحت الشواية لمدة 4-5 دقائق على كل جانب حتى تنضج تمامًا.", "قدّمه في رغيف من القمح الكامل محشوًا بالخس والطماطم والخيار والبصل الأحمر. زيّنه بالشبت وربع ليمونة."],
 ["جرّب استخدام أنواع أخرى من السمك الأبيض مثل سمك الفحم (كولي).", "يمكنك أيضًا استخدام أعشاب مختلفة، مثل البقدونس.", "هذه القطع لذيذة أيضًا عند تقديمها مع الخضار وصلصة البقدونس.", "تعليمات التجميد: يمكن تجميدها بشرط ألا يكون السمك قد جُمّد سابقًا. يمكنك تجميدها قبل الطهي أو بعده. جمّد قطع برغر السمك في حصص فردية، ثم اتركها تذوب في الثلاجة وحضّرها كما هو موضح أعلاه حتى تصبح ساخنة جدًا في كل جزء منها.", FVH], [])))
R.append((7583393,
("Tartaletas de salmón y espinaca con masa filo", "Estas impresionantes tartaletas son ideales para servir a su familia y amigos.", "4", "220 g",
 ["1 cucharada de aceite vegetal", "100 g de masa filo", "1 pimiento amarillo, picado", "4 cebollas verdes, en rodajas finas", "75 g de espinaca cocida y escurrida (la congelada descongelada es ideal)", "1 buena pizca de pimienta", "15 g de eneldo, picado en trozos grandes, reservando 4 ramitas para decorar", "2 filetes de salmón sin espinas ni piel (aprox. 125 g cada uno), cortados en cubitos", "1 huevo, batido con 100 ml de leche", "8 tomates cherry, en rodajas", "gajos de limón, para decorar"],
 ["Precaliente el horno a 180 °C (gas 4). Para la masa filo, rocíe ligeramente con aceite una bandeja grande para hornear, coloque encima, boca abajo, 4 moldes aptos para horno (de aprox. 10 cm de ancho y 2 cm de profundidad) y rocíe con un poco de aceite.", "Reparta la mezcla entre las bases de masa, agregue el salmón a cada una y vierta por encima la mezcla de leche y huevo.", "Acomode 3 cuadros de masa filo, con el lado engrasado hacia abajo, sobre cada uno de los moldes para crear una forma de flor.", "Cubra con cuidado con un paño de cocina húmedo y reserve.", "Rocíe ligeramente un poco de aceite en una sartén y agregue el pimiento amarillo. Cocine de 3 a 4 minutos, hasta que se ablande, y añada las cebollas verdes. Cocine 1 minuto más, luego incorpore la espinaca, la pimienta y el eneldo picado.", "Reparta la mezcla entre las bases de masa, agregue el salmón a cada una y vierta por encima la mezcla de leche y huevo.", "Cubra con las mitades de tomate y use un recorte de masa arrugado para hacer una forma en el centro.", "Hornee durante 15 minutos. Sirva cubierto con una ramita de eneldo y un gajo de limón a un lado."],
 ["Asegúrese de mantener la masa filo húmeda en todo momento. Cúbrala con un paño de cocina húmedo hasta que la use. Prepare las bases de filo justo antes de rellenarlas.", "Si no tiene moldes pequeños aptos para horno, puede hacer una sola tarta grande.", FVH], []),
("فطائر السلمون والسبانخ بعجينة الفيلو", "هذه الفطائر المميزة رائعة للتقديم لعائلتك وأصدقائك.", "4", "220 غ",
 ["1 ملعقة كبيرة من الزيت النباتي", "100 غ من عجينة الفيلو", "1 حبة فلفل رومي أصفر، مقطعة", "4 حبات بصل أخضر، مقطعة إلى شرائح رفيعة", "75 غ من السبانخ المطبوخة والمصفاة (المجمدة المذابة مثالية)", "رشة كبيرة من الفلفل", "15 غ من الشبت، مفروم تقطيعًا خشنًا مع الاحتفاظ بـ 4 أغصان للتزيين", "2 شريحة سلمون منزوعة العظم والجلد (حوالي 125 غ لكل شريحة)، مقطعة إلى مكعبات صغيرة", "1 بيضة، مخفوقة مع 100 مل من الحليب", "8 حبات طماطم كرزية، مقطعة إلى شرائح", "أرباع ليمون، للتزيين"],
 ["سخّن الفرن مسبقًا على 180° مئوية (درجة الغاز 4). بالنسبة لعجينة الفيلو، رشّ صينية خَبز كبيرة برذاذ خفيف من الزيت، وضع عليها 4 أطباق مقاومة للحرارة (بعرض حوالي 10 سم وعمق 2 سم) مقلوبة، ورشّها بقليل من الزيت.", "وزّع الخليط على قواعد العجين وضع السلمون في كل قاعدة واسكب فوقها خليط الحليب والبيض.", "رتّب 3 مربعات من الفيلو، مع جعل الجانب المدهون إلى الأسفل، فوق كل طبق لتكوين شكل زهرة.", "غطِّها بعناية بمنشفة مطبخ مبللة وضعها جانبًا.", "رشّ مقلاة برذاذ خفيف من الزيت وأضف الفلفل الرومي الأصفر. اطهه لمدة 3-4 دقائق حتى يلين، ثم أضف البصل الأخضر. اطهه دقيقة إضافية، ثم أضف السبانخ والفلفل والشبت المفروم مع التحريك.", "وزّع الخليط على قواعد العجين وضع السلمون في كل قاعدة واسكب فوقها خليط الحليب والبيض.", "ضع نصفي الطماطم في الأعلى واستخدم قطعة مكرمشة من بقايا العجين لتشكيل رسم في الوسط.", "اخبزها لمدة 15 دقيقة. قدّمها مزيّنة بغصن شبت وربع ليمونة على الجانب."],
 ["احرص على إبقاء عجينة الفيلو رطبة طوال الوقت. غطِّها بمنشفة مطبخ مبللة إلى أن تستخدمها. لا تصنع قواعد الفيلو إلا قبل ملئها مباشرة.", "إذا لم تتوفر لديك أطباق صغيرة مقاومة للحرارة، فيمكنك صنع فطيرة كبيرة واحدة.", FVH], [])))
